"""Generated files are rebuilt when work lands instead of sending it back
(`generated-files-are-rebuilt-when-work-lands-instead-of-sending-it-back`, task `rebuild`).

A fixture project whose `gen.txt` is produced by `gen.py` from `a.txt` and `b.txt`. Two tasks branch
from the same commit, one editing `a.txt` and one `b.txt`, each committing its own rebuilt `gen.txt`:
their sources merge cleanly and their `gen.txt` conflicts. Real git and real commands throughout.

The project's setting is `Project.generated_files`, set here directly on the row as the operator's
settings route stores it.
"""

from __future__ import annotations

import os
import sys
from pathlib import Path
from types import SimpleNamespace

import pytest
from sqlalchemy import select

from hub import generated_files, project_checks
from hub.db import models
from hub.db.engine import async_session_factory
from hub.db.models import AIJob, Loop, Project, Task
from hub.worktrees import task_branch_name

from .test_task_integration import git, make_repo, set_main_branch

TASKS = "/api/v1/projects/proj-test/tasks"
PY = f'"{sys.executable}"'
GEN = (
    "from pathlib import Path\n"
    "a = Path('a.txt').read_text(encoding='utf-8')\n"
    "b = Path('b.txt').read_text(encoding='utf-8')\n"
    "Path('gen.txt').write_text('generated\\n' + a + b, encoding='utf-8', newline='\\n')\n"
)
T1, T2 = "task-9e4f00000001", "task-9e4f00000002"


def queue():
    from hub import landing_queue

    return landing_queue


@pytest.fixture(autouse=True)
def _a_long_gather_window(monkeypatch):
    monkeypatch.setattr(queue(), "BATCH_GATHER_SECONDS", 3600.0)
    yield
    queue().cancel_timers()


def generated(text_a, text_b):
    return "generated\n" + text_a + text_b


def write(root: Path, name: str, content: str) -> None:
    (root / name).write_bytes(content.encode("utf-8"))


def commit_files(root: Path, branch: str, files: dict, *, create=True) -> str:
    git(root, "checkout", "-q", *(["-b", branch] if create else [branch]))
    for name, content in files.items():
        write(root, name, content)
    git(root, "add", *files)
    git(root, "commit", "-q", "-m", f"work on {', '.join(files)}")
    sha = git(root, "rev-parse", "HEAD").stdout.strip()
    git(root, "checkout", "-q", "main")
    return sha


async def declare(command=None, *, paths=("gen.txt",), timeout=60):
    """The project declares *paths* generated by *command* (default: `gen.py`), through the
    operator's setting, `Project.generated_files`."""
    raw = {"paths": list(paths), "command": command or f"{PY} gen.py", "timeout_seconds": timeout}
    async with async_session_factory() as session:
        (await session.get(Project, "proj-test")).generated_files = raw
        await session.commit()
    return generated_files.settings_of(SimpleNamespace(generated_files=raw))


def script(tmp_path_factory, body: str) -> str:
    """A command running *body* as Python from outside the repository, in the scratch worktree."""
    path = tmp_path_factory.mktemp("cmd") / "cmd.py"
    path.write_text(body, encoding="utf-8")
    return f'{PY} "{path}"'


async def fixture_project(tmp_path, *, a2="a2\n", b2="b2\n", t1_extra=None, t2_extra=None):
    """main holds gen.py, a.txt, b.txt and gen.txt; T1 edits a.txt and T2 edits b.txt, each with
    its own rebuilt gen.txt. Both are under review in a loop whose approval merges branch tips."""
    make_repo(tmp_path)
    write(tmp_path, "gen.py", GEN)
    write(tmp_path, "a.txt", "a1\n")
    write(tmp_path, "b.txt", "b1\n")
    write(tmp_path, "gen.txt", generated("a1\n", "b1\n"))
    git(tmp_path, "add", "gen.py", "a.txt", "b.txt", "gen.txt")
    git(tmp_path, "commit", "-q", "-m", "fixture")
    await set_main_branch("main")
    async with async_session_factory() as session:
        session.add(
            AIJob(
                id="job-gen",
                project_id="proj-test",
                name="gen",
                agent="builder",
                message="work",
                cron="*/5 * * * *",
                session_mode="new",
                enabled=False,
            )
        )
        await session.flush()
        session.add(
            Loop(
                id="loop-gen",
                project_id="proj-test",
                job_id="job-gen",
                purpose="work",
                work_needs_evidence=False,
            )
        )
        await session.flush()
        for n, task_id in enumerate((T1, T2), start=1):
            session.add(
                Task(
                    id=task_id,
                    loop_id="loop-gen",
                    project_id="proj-test",
                    title=f"Work {n}",
                    description="",
                    status="under_review",
                    assignee="builder",
                )
            )
        await session.commit()
    one = {"a.txt": a2, "gen.txt": generated(a2, "b1\n"), **(t1_extra or {})}
    two = {"b.txt": b2, "gen.txt": generated("a1\n", b2), **(t2_extra or {})}
    return commit_files(tmp_path, task_branch_name(T1), one), commit_files(
        tmp_path, task_branch_name(T2), two
    )


async def approve(app, auth_headers, task_id):
    return await app.patch(f"{TASKS}/{task_id}", json={"status": "approved"}, headers=auth_headers)


async def land_first_then(app, auth_headers):
    """T1 is approved and lands alone; then T2 is approved, its gen.txt now conflicting."""
    assert (await approve(app, auth_headers, T1)).status_code == 200
    await queue().drain()
    approved = await approve(app, auth_headers, T2)
    return approved


async def status_of(task_id):
    async with async_session_factory() as session:
        return (await session.get(Task, task_id, populate_existing=True)).status


async def latest_landing(task_id):
    async with async_session_factory() as session:
        return await queue().latest_landing(session, task_id)


def show(root, ref, path):
    return git(root, "show", f"{ref}:{path}").stdout


def main_sha(root):
    return git(root, "rev-parse", "main").stdout.strip()


# --- FR-2: unset is unchanged ---------------------------------------------------------------------


@pytest.mark.asyncio
async def test_unset_sends_back_as_today_at_every_point(app, auth_headers, tmp_path):
    """ac-unset: no generated paths -> the landing batch sends the second back with today's report,
    the check run ends in a conflict, and the PR's preparation reports the conflict."""
    one, two = await fixture_project(tmp_path)
    async with async_session_factory() as session:
        (await session.get(Project, "proj-test")).checks = [
            {"name": "ok", "command": f"{PY} -c pass", "timeout_seconds": 60}
        ]
        await session.commit()
    for task_id in (T1, T2):
        assert (await approve(app, auth_headers, task_id)).status_code == 200
    await queue().drain()

    assert await status_of(T1) == "approved"
    assert await status_of(T2) == "revision_needed"
    landing = await latest_landing(T2)
    assert landing.state == "sent_back"
    assert (
        "does not merge cleanly onto the work of" in landing.reason and "gen.txt" in landing.reason
    )
    assert generated_files.GENERATED_SUFFIX not in git(tmp_path, "log", "-1", "--format=%B").stdout

    tip = main_sha(tmp_path)
    built, why, conflict = project_checks.merge_for_checks(tmp_path, tip, [two])
    assert built is None and conflict and "gen.txt" in why and "rebuilding" not in why

    from hub.pull_requests import prepare

    remote = _bare_remote(tmp_path)
    prepared = prepare(tmp_path, remote, "main", "aw-build-x", T2, [two])
    assert prepared.conflict == ["gen.txt"] and prepared.rebuild_failure is None


@pytest.mark.asyncio
async def test_unset_approval_after_the_first_landed_is_refused_as_today(
    app, auth_headers, tmp_path
):
    await fixture_project(tmp_path)
    refused = await land_first_then(app, auth_headers)
    assert refused.status_code == 409, refused.text
    assert refused.json()["detail"]["unmergeable"][0]["paths"] == ["gen.txt"]


# --- FR-3: the three conflict points --------------------------------------------------------------


@pytest.mark.asyncio
async def test_the_landing_batch_rebuilds_instead_of_sending_back(
    app, auth_headers, tmp_path, monkeypatch
):
    """ac-three-points (landing batch), and the gate: both approved together land, and T2 approved
    after T1 landed is not refused."""
    await declare()
    await fixture_project(tmp_path)
    for task_id in (T1, T2):
        assert (await approve(app, auth_headers, task_id)).status_code == 200
    await queue().drain()

    assert [await status_of(T1), await status_of(T2)] == ["approved", "approved"]
    assert (await latest_landing(T2)).state == "landed"
    assert show(tmp_path, "main", "gen.txt") == generated("a2\n", "b2\n")
    assert show(tmp_path, "main", "a.txt") == "a2\n" and show(tmp_path, "main", "b.txt") == "b2\n"
    assert git(tmp_path, "status", "--porcelain").stdout == "", "the checkout followed main"


@pytest.mark.asyncio
async def test_approval_is_not_refused_for_a_generated_only_conflict(
    app, auth_headers, tmp_path, monkeypatch
):
    await declare()
    await fixture_project(tmp_path)
    approved = await land_first_then(app, auth_headers)
    assert approved.status_code == 200, approved.text
    await queue().drain()
    assert await status_of(T2) == "approved"
    assert show(tmp_path, "main", "gen.txt") == generated("a2\n", "b2\n")


@pytest.mark.asyncio
async def test_the_check_run_before_review_rebuilds(
    app, auth_headers, tmp_path, tmp_path_factory, monkeypatch
):
    """ac-three-points (check run): T2's run on a main holding T1 is not ended by the conflict;
    the checks run on the rebuilt tree and the run records what was rebuilt."""
    await declare()
    one, two = await fixture_project(tmp_path)
    assert (await approve(app, auth_headers, T1)).status_code == 200
    await queue().drain()
    seen = tmp_path_factory.mktemp("seen") / "gen.txt"
    check = {
        "name": "copy",
        "command": script(
            tmp_path_factory,
            f"import shutil\nshutil.copy('gen.txt', r'{seen}')\n",
        ),
        "timeout_seconds": 60,
    }
    async with async_session_factory() as session:
        (await session.get(Project, "proj-test")).checks = [check]
        await session.commit()

    run_id = await project_checks.request_run("proj-test", T2, targets=[two])
    await project_checks.drain()

    async with async_session_factory() as session:
        run = await session.get(models.TaskCheckRun, run_id)
    assert run.state == "passed", (run.state, run.error, run.results)
    assert run.ended_by is None
    assert seen.read_text(encoding="utf-8") == generated("a2\n", "b2\n")
    assert show(tmp_path, run.merged_sha, "gen.txt") == generated("a2\n", "b2\n")
    first = run.results[0]
    assert first["name"] == project_checks.REBUILD_RESULT
    assert first["regenerated"]["paths"] == ["gen.txt"]
    assert first["regenerated"]["seconds"] >= 0
    assert await status_of(T2) == "under_review"


def _bare_remote(tmp_path) -> str:
    bare = tmp_path.parent / f"{tmp_path.name}-remote.git"
    git(tmp_path.parent, "init", "-q", "--bare", str(bare))
    git(tmp_path, "remote", "add", "origin", str(bare))
    git(tmp_path, "push", "-q", "origin", "main")
    return "origin"


@pytest.mark.asyncio
async def test_the_push_to_a_builds_pr_rebuilds(app, auth_headers, tmp_path, monkeypatch):
    """ac-three-points (PR push): with a local bare remote standing in for GitHub, whose main holds
    T1's work, T2's preparation for the PR merges with gen.txt rebuilt."""
    from hub.pull_requests import prepare

    settings = await declare()
    one, two = await fixture_project(tmp_path)
    git(tmp_path, "merge", "-q", "--no-ff", "-m", "T1", one)
    remote = _bare_remote(tmp_path)

    prepared = prepare(tmp_path, remote, "main", "aw-build-x", T2, [two], settings)

    assert not prepared.conflict and not prepared.error, prepared
    assert show(tmp_path, prepared.merged, "gen.txt") == generated("a2\n", "b2\n")
    assert prepared.regenerated[0]["paths"] == ["gen.txt"]
    message = git(tmp_path, "log", "-1", "--format=%B", prepared.merged).stdout.strip()
    assert message.endswith(generated_files.GENERATED_SUFFIX.strip())


# --- FR-4: a source conflict is still sent back, and nothing runs --------------------------------


@pytest.mark.asyncio
async def test_a_source_conflict_is_sent_back_and_the_command_does_not_run(
    app, auth_headers, tmp_path, tmp_path_factory, monkeypatch
):
    marker = tmp_path_factory.mktemp("marker") / "ran"
    await declare(
        script(tmp_path_factory, f"open(r'{marker}', 'w').write('ran')\n"),
    )
    await fixture_project(tmp_path, t2_extra={"a.txt": "a-from-two\n"})
    for task_id in (T1, T2):
        assert (await approve(app, auth_headers, task_id)).status_code == 200
    await queue().drain()

    assert await status_of(T2) == "revision_needed"
    landing = await latest_landing(T2)
    assert "a.txt" in landing.reason
    assert not marker.exists(), "the command ran for a conflict outside the declared paths"


@pytest.mark.asyncio
async def test_approval_is_refused_for_a_conflict_also_outside_the_declared_paths(
    app, auth_headers, tmp_path, tmp_path_factory, monkeypatch
):
    marker = tmp_path_factory.mktemp("marker") / "ran"
    await declare(script(tmp_path_factory, f"open(r'{marker}', 'w').write('ran')\n"))
    await fixture_project(tmp_path, t2_extra={"a.txt": "a-from-two\n"})
    refused = await land_first_then(app, auth_headers)
    assert refused.status_code == 409, refused.text
    assert sorted(refused.json()["detail"]["unmergeable"][0]["paths"]) == ["a.txt", "gen.txt"]
    assert not marker.exists()


# --- FR-5: only declared paths are committed ------------------------------------------------------


async def _sent_back_with(app, auth_headers, tmp_path, monkeypatch, command, *, timeout=60):
    await declare(command, timeout=timeout)
    await fixture_project(tmp_path)
    for task_id in (T1, T2):
        assert (await approve(app, auth_headers, task_id)).status_code == 200
    before_t1 = main_sha(tmp_path)
    await queue().drain()
    assert await status_of(T2) == "revision_needed"
    # T1 landed alone: main has one integration and no rebuilt commit.
    log = git(tmp_path, "log", "--format=%s", f"{before_t1}..main").stdout
    assert generated_files.GENERATED_SUFFIX.strip() not in log
    assert show(tmp_path, "main", "b.txt") == "b1\n"
    landing = await latest_landing(T2)
    assert landing.state == "sent_back"
    return landing.reason


@pytest.mark.asyncio
async def test_a_command_that_changes_a_source_file_commits_nothing(
    app, auth_headers, tmp_path, tmp_path_factory, monkeypatch
):
    command = script(
        tmp_path_factory,
        "import runpy\nrunpy.run_path('gen.py')\n"
        "open('a.txt', 'a', encoding='utf-8').write('touched\\n')\n",
    )
    reason = await _sent_back_with(app, auth_headers, tmp_path, monkeypatch, command)
    assert "not declared generated: a.txt" in reason


@pytest.mark.asyncio
async def test_a_command_that_fails_commits_nothing(
    app, auth_headers, tmp_path, tmp_path_factory, monkeypatch
):
    command = script(tmp_path_factory, "print('the generator broke')\nraise SystemExit(1)\n")
    reason = await _sent_back_with(app, auth_headers, tmp_path, monkeypatch, command)
    assert "exited 1" in reason and "the generator broke" in reason


@pytest.mark.asyncio
async def test_a_command_past_its_timeout_commits_nothing(
    app, auth_headers, tmp_path, tmp_path_factory, monkeypatch
):
    command = script(tmp_path_factory, "import time\ntime.sleep(30)\n")
    reason = await _sent_back_with(app, auth_headers, tmp_path, monkeypatch, command, timeout=2)
    assert "2s timeout" in reason


# --- FR-6: the rebuilt tree is checked ------------------------------------------------------------


@pytest.mark.asyncio
async def test_the_landings_check_runs_on_the_rebuilt_tree(
    app, auth_headers, tmp_path, tmp_path_factory, monkeypatch
):
    await declare(
        script(
            tmp_path_factory,
            "import runpy\nrunpy.run_path('gen.py')\n"
            "open('gen.txt', 'a', encoding='utf-8').write('BAD\\n')\n",
        ),
    )
    await fixture_project(tmp_path)
    assert (await approve(app, auth_headers, T1)).status_code == 200
    await queue().drain()
    landed_t1 = main_sha(tmp_path)
    check = {
        "name": "no-bad",
        "command": script(
            tmp_path_factory,
            "import sys\n"
            "sys.exit(1 if 'BAD' in open('gen.txt', encoding='utf-8').read() else 0)\n",
        ),
        "timeout_seconds": 60,
        "phase": project_checks.PHASE_LANDING,
    }
    async with async_session_factory() as session:
        (await session.get(Project, "proj-test")).checks = [check]
        await session.commit()

    assert (await approve(app, auth_headers, T2)).status_code == 200
    await queue().drain()

    assert main_sha(tmp_path) == landed_t1, "nothing reached main"
    assert await status_of(T2) == "revision_needed"
    async with async_session_factory() as session:
        batch = (
            (
                await session.execute(
                    select(models.LandingBatch).order_by(models.LandingBatch.created_at.desc())
                )
            )
            .scalars()
            .first()
        )
        run = await session.get(models.TaskCheckRun, batch.check_run_id)
    assert "BAD" in show(tmp_path, run.merged_sha, "gen.txt"), "the check ran on the rebuilt tree"
    assert any(r["name"] == "no-bad" and r["exit_code"] == 1 for r in run.results)


# --- FR-7: it runs like a check -------------------------------------------------------------------


@pytest.mark.asyncio
async def test_the_command_runs_in_a_scratch_worktree_without_the_hubs_configuration(
    app, auth_headers, tmp_path, tmp_path_factory, monkeypatch
):
    assert os.environ.get("DATABASE_URL"), "the Hub's database URL is in its environment"
    seen = tmp_path_factory.mktemp("seen") / "where.txt"
    await declare(
        script(
            tmp_path_factory,
            "import os, runpy\nrunpy.run_path('gen.py')\n"
            f"open(r'{seen}', 'w', encoding='utf-8').write("
            "os.getcwd() + '\\n' + str('DATABASE_URL' in os.environ))\n",
        ),
    )
    await fixture_project(tmp_path)
    for task_id in (T1, T2):
        assert (await approve(app, auth_headers, task_id)).status_code == 200
    await queue().drain()

    cwd, has_database_url = seen.read_text(encoding="utf-8").splitlines()
    where = Path(cwd).resolve()
    assert where != tmp_path.resolve()
    assert (tmp_path / ".agentweave").resolve() in where.parents
    assert has_database_url == "False"
    assert not where.exists(), "the scratch worktree is removed after"


# --- FR-8: every rebuild is recorded --------------------------------------------------------------


@pytest.mark.asyncio
async def test_a_rebuild_is_in_the_commit_the_landing_and_the_tasks_history(
    app, auth_headers, tmp_path, monkeypatch
):
    await declare()
    await fixture_project(tmp_path)
    for task_id in (T1, T2):
        assert (await approve(app, auth_headers, task_id)).status_code == 200
    await queue().drain()

    message = git(tmp_path, "log", "-1", "--format=%B", "main").stdout.strip()
    assert message.endswith("(generated files rebuilt)"), message

    landing = (await app.get(f"{TASKS}/{T2}/checks", headers=auth_headers)).json()["landing"]
    assert landing["regenerated"]["paths"] == ["gen.txt"]
    assert landing["regenerated"]["seconds"] >= 0

    history = (await app.get(f"{TASKS}/{T2}/transitions", headers=auth_headers)).json()
    [rebuild] = history["rebuilds"]
    assert rebuild["paths"] == ["gen.txt"] and rebuild["seconds"] >= 0
    assert rebuild["where"] == "landing"
    assert (await app.get(f"{TASKS}/{T1}/transitions", headers=auth_headers)).json()[
        "rebuilds"
    ] == []
